item.command:
/bin/bash -lc "python3 - <<'PY'
import urllib.request
base='https://raw.githubusercontent.com/NVIDIA/cuda-samples/db3eea23946bca2e90a75eca2b5b3e07158a9e11/Samples/5_Domain_Specific/MonteCarloMultiGPU/'
for name in ['MonteCarloMultiGPU.cpp','MonteCarlo_kernel.cu','CMakeLists.txt']:
 try:
  s=urllib.request.urlopen(base+name, timeout=25).read().decode()
  print(name)
  for i,l in enumerate(s.splitlines(),1):
   if name=='CMakeLists.txt' or any(w in l for w in ['sumReserve','nOptions','PATH_N','malloc','Malloc','calloc','srand','curand_init','MAX_OPTIONS','Total time','sdkStartTimer','sdkStopTimer','sizeof','OPT_N']): print(f'{i}: {l}')
 except Exception as e: print(type(e).__name__,str(e))
PY"

